project/contracts/Base.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

abstract contract Base {
    address public immutable owner;

    constructor(address owner_) {
        owner = owner_;
    }
}

project/contracts/Counter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Tally} from "./Tally.sol";

contract Counter {
    uint256 public count;

    function bump(uint256 amount) external {
        count = Tally.add(count, amount);
    }
}

project/contracts/Greeter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {Base} from "./Base.sol";

contract Greeter is Base {
    string public greeting;

    constructor(address owner_, string memory greeting_) Base(owner_) {
        greeting = greeting_;
    }
}

